class MockSecureKey:
    """Production-grade mock for SecureKey with TTL validation."""
    
    def __init__(self, key_id, created_at=None, expires_at=None, ttl=1000):
        self.key_id = key_id
        self.created_at = created_at or time.monotonic()
        self.expires_at = expires_at or (self.created_at + ttl)
        self.public_key = b'\x01' * 1568
        self.ciphertext = b'\x02' * 1568
        self.shared_secret = b'\x03' * 32
    
    @property
    def is_expired(self):
        return time.monotonic() > self.expires_at
    
    def __repr__(self):
        return f"MockSecureKey(id={self.key_id}, expires={self.expires_at:.2f})"


class KeyRotationBuffer:
    """Production implementation of bounded key rotation buffer."""
    
    MAX_ACTIVE_KEYS = 1024
    DEFAULT_TTL_SECONDS = 3600
    
    def __init__(self, max_keys=None, ttl_seconds=None):
        self.max_keys = max_keys or self.MAX_ACTIVE_KEYS
        self.ttl_seconds = ttl_seconds or self.DEFAULT_TTL_SECONDS
        self._keys = {}  # key_id -> MockSecureKey
        self._insertion_order = []  # FIFO tracking
        self._lock = asyncio.Lock()
    
    async def add_key(self, key: MockSecureKey) -> bool:
        """Add key with capacity enforcement and TTL validation."""
        async with self._lock:
            # Validate input
            if not isinstance(key, MockSecureKey):
                raise TypeError("key must be MockSecureKey instance")
            if not key.key_id:
                raise ValueError("key_id cannot be empty")
            
            # TTL validation
            if key.expires_at <= time.monotonic():
                return False  # Already expired
            
            # Capacity enforcement
            if len(self._keys) >= self.max_keys:
                await self._evict_expired()
                if len(self._keys) >= self.max_keys:
                    # Force FIFO eviction
                    oldest_id = self._insertion_order.pop(0)
                    del self._keys[oldest_id]
            
            # Insert
            self._keys[key.key_id] = key
            self._insertion_order.append(key.key_id)
            return True
    
    async def _evict_expired(self):
        """Remove expired keys."""
        now = time.monotonic()
        expired_ids = [
            kid for kid, k in self._keys.items() 
            if k.is_expired or k.expires_at <= now
        ]
        for kid in expired_ids:
            del self._keys[kid]
            if kid in self._insertion_order:
                self._insertion_order.remove(kid)
    
    async def get_active_count(self) -> int:
        """Return count of non-expired keys."""
        await self._evict_expired()
        return len(self._keys)
    
    async def get_key(self, key_id: str):
        """Retrieve key by ID, None if not found or expired."""
        async with self._lock:
            key = self._keys.get(key_id)
            if key and not key.is_expired:
                return key
            return None
    
    async def rotate(self) -> int:
        """Force rotation: evict expired, return count removed."""
        async with self._lock:
            before = len(self._keys)
            await self._evict_expired()
            return before - len(self._keys)


