class TestConcurrency:
    """Verify async race condition safety."""
    
    @pytest.mark.asyncio
    async def test_concurrent_adds(self, buffer):
        """Concurrent adds maintain integrity."""
        async def add_keys(start, count):
            for i in range(start, start + count):
                key = MockSecureKey(key_id=f"conc_{i}", ttl=1000)
                await buffer.add_key(key)
        
        # Launch concurrent tasks
        tasks = [
            add_keys(0, 100),
            add_keys(100, 100),
            add_keys(200, 100)
        ]
        await asyncio.gather(*tasks)
        
        count = await buffer.get_active_count()
        assert count == 300, f"Concurrent adds lost keys: {count}"
    
    @pytest.mark.asyncio
    async def test_concurrent_read_write(self, buffer):
        """Concurrent reads during writes don't corrupt."""
        async def writer():
            for i in range(50):
                key = MockSecureKey(key_id=f"rw_{i}", ttl=1000)
                await buffer.add_key(key)
                await asyncio.sleep(0.001)
        
        async def reader():
            for _ in range(50):
                await buffer.get_active_count()
                await asyncio.sleep(0.001)
        
        await asyncio.gather(writer(), reader())
        
        count = await buffer.get_active_count()
        assert count == 50
    
    @pytest.mark.asyncio
    async def test_lock_prevents_race_condition(self):
        """Lock ensures atomic operations."""
